final class Person {
    let name: String
    init(name: String) {
        self.name = name
        print("\(name) initialised")
    }
    deinit { print("\(name) deallocated") }
}

do {
    let ada = Person(name: "Ada")   // count = 1
    let alias = ada                 // count = 2
    _ = alias
}                                   // both go out of scope → count = 0 → deinit

// prints:
// Ada initialised
// Ada deallocated

final class Customer {
    let name: String
    var card: CreditCard?          // strong: customer owns the card
    init(name: String) { self.name = name }
    deinit { print("Customer gone") }
}

final class CreditCard {
    let number: String
    unowned let customer: Customer // a card can't outlive its customer
    init(number: String, customer: Customer) {
        self.number = number
        self.customer = customer
    }
    deinit { print("Card gone") }
}

// weak, by contrast, must be a var and optional
final class Screen {
    weak var delegate: ScreenDelegate?   // delegate may vanish at any time
}
protocol ScreenDelegate: AnyObject {}

final class Parent {
    var child: Child?
    deinit { print("Parent gone") }
}

final class Child {
    var parent: Parent?          // strong both ways → cycle
    deinit { print("Child gone") }
}

do {
    let p = Parent(); let c = Child()
    p.child = c
    c.parent = p
}
// prints nothing. Both leaked.

// The fix: one side stops insisting
final class FixedChild {
    weak var parent: Parent?     // child does not own its parent
    deinit { print("Child gone") }
}

final class Downloader {
    var completion: (() -> Void)?
    var progress = 0.0

    func brokenSetup() {
        completion = { self.finish() }        // cycle: self → closure → self
    }

    func fixedSetup() {
        completion = { [weak self] in
            guard let self else { return }    // object gone: do nothing, deliberately
            self.finish()
        }
    }

    func snapshot() {
        let at = progress
        completion = { print("was \(at)") }   // captures a copy, not self
    }

    func finish() {}
}
